	private boolean blockIgnoringInterrupts() {
		boolean interrupted = false;
		try {
			while (true) {
				try {
					return release.await(30, TimeUnit.SECONDS);
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
		} finally {
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private void addIncomingLinks(IRI target, int count) {
		try (RepositoryConnection connection = store.getConnection()) {
			connection.begin();
			for (int i = 0; i < count; i++) {
				connection.add(VF.createIRI(NS + "s" + i), LINK, target);
			}
			connection.commit();
		}
	}

	/** Counts every statement the repository hands to Explore's handlers. */
	private Repository counting(Repository repository) {
		return new RepositoryWrapper(repository) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public void exportStatements(Resource subj, IRI pred, Value obj, boolean includeInferred,
							RDFHandler handler, Resource... contexts) throws RepositoryException, RDFHandlerException {
						getDelegate().exportStatements(subj, pred, obj, includeInferred, new AbstractRDFHandler() {
							@Override
							public void handleStatement(Statement statement) throws RDFHandlerException {
								streamed.incrementAndGet();
								handler.handleStatement(statement);
							}
						}, contexts);
					}
				};
			}

			@Override
			public void shutDown() {
				// the store is shut down by the test
			}
		};
	}

	/** A repository whose statement scans and queries wait until the test ends. */
	private Repository blocking(Repository repository) {
		return new RepositoryWrapper(repository) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public void exportStatements(Resource subj, IRI pred, Value obj, boolean includeInferred,
							RDFHandler handler, Resource... contexts) throws RepositoryException, RDFHandlerException {
						try {
							release.await(30, TimeUnit.SECONDS);
						} catch (InterruptedException e) {
							Thread.currentThread().interrupt();
						}
					}
				};
			}

			@Override
			public void shutDown() {
				// the store is shut down by the test
			}
		};
	}

	/** An Explore servlet with the given cookie handler, which the base servlet keeps in a protected field. */
	private static final class TestExploreServlet extends ExploreServlet {

		private final Repository counted;

		private TestExploreServlet(long budgetMillis, Repository repository, CookieHandler cookies) {
			super(budgetMillis);
			this.counted = repository;
			setRepository(repository);
			this.cookies = cookies;
		}
	}

	private static TestExploreServlet servlet(Repository repository, CookieHandler cookies) {
		return new TestExploreServlet(BrowseList.BROWSE_BUDGET_MILLIS, repository, cookies);
	}

	private static void service(TestExploreServlet servlet, WorkbenchRequest request, TupleResultBuilder builder)
			throws Exception {
		try (RepositoryConnection connection = servlet.counted.getConnection()) {
			servlet.service(request, mock(HttpServletResponse.class), builder, connection);
		} finally {
			servlet.destroy();
		}
	}

	private static WorkbenchRequest request(Value resource, int knownTotal, int offset, Integer limit)
			throws BadRequestException {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		when(request.getValue("resource")).thenReturn(resource);
		when(request.getInt("know_total")).thenReturn(knownTotal);
		when(request.getInt("offset")).thenReturn(offset);
		when(request.isParameterPresent(ExploreServlet.LIMIT)).thenReturn(limit != null);
		if (limit != null) {
			when(request.getInt(ExploreServlet.LIMIT)).thenReturn(limit);
		}
		when(request.getParameter(anyString())).thenReturn(null);
		return request;
	}

	private static List<Object[]> rows(TupleResultBuilder builder) {
		List<Object[]> rows = new ArrayList<>();
		mockingDetails(builder)
				.getInvocations()
				.stream()
				.filter(invocation -> invocation.getMethod().getName().equals("result"))
				.forEach(invocation -> rows.add(invocation.getArguments()));
		return rows;
	}

	private static RepositoryResult<Namespace> emptyNamespaces() {
		return new RepositoryResult<>(new CloseableIteratorIteration<>(List.<Namespace>of().iterator()));
	}

	private static final class ErrorExploreServlet extends ExploreServlet {
		private final TupleResultBuilder initialBuilder;
		private final TupleResultBuilder errorBuilder;
		private int builderCalls;

		private ErrorExploreServlet(TupleResultBuilder initialBuilder, TupleResultBuilder errorBuilder) {
			this.initialBuilder = initialBuilder;
			this.errorBuilder = errorBuilder;
		}

		@Override
		protected TupleResultBuilder getTupleResultBuilder(HttpServletRequest req, HttpServletResponse resp,
				OutputStream outputStream) {
			return builderCalls++ == 0 ? initialBuilder : errorBuilder;
		}

		@Override
		protected void service(WorkbenchRequest req, HttpServletResponse resp, TupleResultBuilder builder,
				RepositoryConnection con) throws BadRequestException {
			throw new BadRequestException("broken resource");
		}
	}

